from pathlib import Path
import sys
p=Path(sys.argv[1])
s=p.read_text(encoding='utf-8-sig').replace('\r\n','\n')

def rep(old,new,label):
    global s
    if old not in s: raise SystemExit('v1.9 windows anchor missing: '+label)
    s=s.replace(old,new,1)

rep('#include "VBCableBridge.h"\n', '#include "VBCableBridge.h"\n#include "NoiseCleaner.h"\n#include "qrcodegen.hpp"\n', 'includes')
rep('constexpr UINT WM_PB_CABLE_STATE = WM_APP + 6;\n', 'constexpr UINT WM_PB_CABLE_STATE = WM_APP + 6;\nconstexpr UINT WM_PB_NOISE_STATE = WM_APP + 7;\n', 'message')
rep('constexpr int IDC_COPY_ADDRESS = 1027;\n', '''constexpr int IDC_COPY_ADDRESS = 1027;\nconstexpr int IDC_SHOW_QR = 1028;\nconstexpr int IDC_NOISE_MODE = 1029;\nconstexpr int IDC_NOISE_STATE = 1030;\n''','ids')
rep('HWND g_copyAddress{};\n', '''HWND g_copyAddress{};\nHWND g_showQr{};\nHWND g_noiseMode{};\nHWND g_noiseState{};\n''','handles')
rep('std::atomic<bool> g_vbCableEnabled{false};\n', '''std::atomic<bool> g_vbCableEnabled{false};\nNoiseCleaner g_noiseCleaner;\nstd::mutex g_qrMutex;\nstd::string g_qrToken;\nULONGLONG g_qrExpiry=0;\nstd::vector<uint8_t> g_qrModules;\nint g_qrSize=0;\n''','globals')
rep('    int quality = 92;\n', '    int quality = 92;\n    int noiseMode = 0;\n', 'prefs field')
rep('        else if(k==L"quality") p.quality=parseInt(v,p.quality,55,95);\n', '        else if(k==L"quality") p.quality=parseInt(v,p.quality,55,95);\n        else if(k==L"noise_mode") p.noiseMode=parseInt(v,p.noiseMode,0,2);\n', 'prefs load')
rep('    out<<L"quality="<<g_uiPrefs.quality<<L"\\n";\n', '    out<<L"quality="<<g_uiPrefs.quality<<L"\\n";\n    out<<L"noise_mode="<<g_uiPrefs.noiseMode<<L"\\n";\n', 'prefs save')
rep('std::string extractDevice(const std::vector<uint8_t>& v){ std::string s(v.begin(),v.end()); auto p=s.find("\\\"device\\\":\\\""); if(p==std::string::npos) return "Phone"; p+=10; auto e=s.find(\'"\',p); return e==std::string::npos?"Phone":s.substr(p,e-p); }\n', '''std::string extractDevice(const std::vector<uint8_t>& v){ std::string s(v.begin(),v.end()); auto p=s.find("\\\"device\\\":\\\""); if(p==std::string::npos) return "Phone"; p+=10; auto e=s.find('"',p); return e==std::string::npos?"Phone":s.substr(p,e-p); }\nstd::string extractJsonString(const std::vector<uint8_t>& v,const char* key){\n    std::string s(v.begin(),v.end()); std::string token=std::string("\\\"")+key+"\\\":\\\"";\n    auto p=s.find(token); if(p==std::string::npos) return {}; p+=token.size(); auto e=s.find('"',p);\n    return e==std::string::npos?std::string{}:s.substr(p,e-p);\n}\n''','json helper')

anchor='''std::wstring localIps(){\n    char host[256]{}; if(gethostname(host,sizeof(host))!=0) return L""; addrinfo hints{}; hints.ai_family=AF_INET; addrinfo* res=nullptr; if(getaddrinfo(host,nullptr,&hints,&res)!=0) return L"";\n    std::wstring out; bool first=true; for(auto* p=res;p;p=p->ai_next){ auto* a=(sockaddr_in*)p->ai_addr; char ip[INET_ADDRSTRLEN]{}; inet_ntop(AF_INET,&a->sin_addr,ip,sizeof(ip)); if(!first) out+=L", "; out+=widen(ip); first=false; } freeaddrinfo(res); return out;\n}\n'''
insert=anchor+'''\nstd::wstring preferredLocalIp(){\n    char host[256]{}; if(gethostname(host,sizeof(host))!=0) return L"";\n    addrinfo hints{}; hints.ai_family=AF_INET; addrinfo* res=nullptr; if(getaddrinfo(host,nullptr,&hints,&res)!=0) return L"";\n    std::wstring fallback;\n    for(auto* p=res;p;p=p->ai_next){\n        auto* a=(sockaddr_in*)p->ai_addr; uint32_t ip=ntohl(a->sin_addr.s_addr);\n        if((ip>>24)==127) continue;\n        char buf[INET_ADDRSTRLEN]{}; inet_ntop(AF_INET,&a->sin_addr,buf,sizeof(buf)); std::wstring w=widen(buf);\n        if(fallback.empty()) fallback=w;\n        bool priv=((ip&0xff000000u)==0x0a000000u)||((ip&0xfff00000u)==0xac100000u)||((ip&0xffff0000u)==0xc0a80000u);\n        if(priv){ freeaddrinfo(res); return w; }\n    }\n    freeaddrinfo(res); return fallback;\n}\nstd::string makeQrToken(){\n    std::random_device rd; std::mt19937_64 gen(((uint64_t)rd()<<32)^rd()^GetTickCount64());\n    std::ostringstream ss; ss<<std::hex<<std::setfill('0'); for(int i=0;i<2;i++) ss<<std::setw(16)<<gen(); return ss.str();\n}\nbool consumeQrToken(const std::string& token){\n    if(token.empty()) return false; std::lock_guard<std::mutex> lk(g_qrMutex);\n    if(g_qrToken.empty() || token!=g_qrToken || GetTickCount64()>g_qrExpiry) return false;\n    g_qrToken.clear(); g_qrExpiry=0; return true;\n}\nLRESULT CALLBACK QrWndProc(HWND hwnd,UINT msg,WPARAM wp,LPARAM lp){\n    if(msg==WM_PAINT){\n        PAINTSTRUCT ps{}; HDC dc=BeginPaint(hwnd,&ps); RECT rc{}; GetClientRect(hwnd,&rc);\n        FillRect(dc,&rc,(HBRUSH)GetStockObject(WHITE_BRUSH));\n        int q=4, total=g_qrSize+q*2; int usable=std::min(rc.right-40,rc.bottom-105); int cell=std::max(2,usable/std::max(1,total));\n        int side=cell*total, ox=(rc.right-side)/2, oy=18; HBRUSH black=(HBRUSH)GetStockObject(BLACK_BRUSH);\n        for(int y=0;y<g_qrSize;y++) for(int x=0;x<g_qrSize;x++) if(g_qrModules[(size_t)y*g_qrSize+x]){\n            RECT m{ox+(x+q)*cell,oy+(y+q)*cell,ox+(x+q+1)*cell,oy+(y+q+1)*cell}; FillRect(dc,&m,black);\n        }\n        SetBkMode(dc,TRANSPARENT); SetTextColor(dc,RGB(35,38,43)); RECT tr{20,oy+side+8,rc.right-20,rc.bottom-8};\n        DrawTextW(dc,L"Scan in PhoneBridge Android > Settings > Scan pairing QR\\nOne-time token • valid for 2 minutes • used once",-1,&tr,DT_CENTER|DT_WORDBREAK);\n        EndPaint(hwnd,&ps); return 0;\n    }\n    if(msg==WM_CLOSE){ DestroyWindow(hwnd); return 0; }\n    return DefWindowProcW(hwnd,msg,wp,lp);\n}\nvoid showPairingQr(HWND owner){\n    std::wstring ip=preferredLocalIp(); if(ip.empty()){ postText(WM_PB_STATUS,L"No usable local IPv4 address was found for QR pairing"); return; }\n    std::string token=makeQrToken();\n    { std::lock_guard<std::mutex> lk(g_qrMutex); g_qrToken=token; g_qrExpiry=GetTickCount64()+120000ull; }\n    std::string payload="phonebridge://pair?host="+narrow(ip)+"&port=8989&token="+token;\n    auto qr=qrcodegen::QrCode::encodeText(payload.c_str(),qrcodegen::QrCode::Ecc::MEDIUM);\n    g_qrSize=qr.getSize(); g_qrModules.assign((size_t)g_qrSize*g_qrSize,0);\n    for(int y=0;y<g_qrSize;y++) for(int x=0;x<g_qrSize;x++) g_qrModules[(size_t)y*g_qrSize+x]=qr.getModule(x,y)?1:0;\n    static bool registered=false; HINSTANCE inst=GetModuleHandleW(nullptr);\n    if(!registered){ WNDCLASSEXW wc{sizeof(wc)}; wc.lpfnWndProc=QrWndProc; wc.hInstance=inst; wc.hCursor=LoadCursor(nullptr,IDC_ARROW); wc.hbrBackground=(HBRUSH)(COLOR_WINDOW+1); wc.lpszClassName=L"PhoneBridgeQrWindow"; RegisterClassExW(&wc); registered=true; }\n    HWND w=CreateWindowExW(WS_EX_DLGMODALFRAME,L"PhoneBridgeQrWindow",L"PhoneBridge • Scan to pair",WS_OVERLAPPED|WS_CAPTION|WS_SYSMENU,CW_USEDEFAULT,CW_USEDEFAULT,500,590,owner,nullptr,inst,nullptr);\n    if(w){ ShowWindow(w,SW_SHOW); UpdateWindow(w); postText(WM_PB_STATUS,L"Pairing QR ready for "+ip+L" • expires in 2 minutes"); }\n}\n\nstd::wstring noiseActivityText(){\n    if(g_noiseCleaner.mode()==NoiseCleaner::Off) return L"Noise Clean: OFF";\n    auto a=g_noiseCleaner.activity();\n    if(a==NoiseCleaner::Learning) return L"Noise Clean: learning background…";\n    if(a==NoiseCleaner::Voice) return L"Noise Clean: voice detected";\n    return L"Noise Clean: noise profile ready";\n}\n'''
if anchor not in s: raise SystemExit('localIps exact anchor missing')
s=s.replace(anchor,insert,1)

rep('for(HWND h:{g_pin,g_share,g_switch,g_torch,g_zoom,g_streamLabel,g_resolution,g_fps,g_quality,g_applyCfg,g_startup,g_openSound,g_openCam,g_vbCable,g_audioDevices,g_getVbCable,g_testCamera,g_repairCamera,g_stats,g_rememberButtons,g_runWith,g_pinEdit,g_savePin,g_addressLabel,g_copyAddress}) showCtrl(h,open);', 'for(HWND h:{g_pin,g_share,g_switch,g_torch,g_zoom,g_streamLabel,g_resolution,g_fps,g_quality,g_applyCfg,g_startup,g_openSound,g_openCam,g_vbCable,g_audioDevices,g_getVbCable,g_testCamera,g_repairCamera,g_stats,g_rememberButtons,g_runWith,g_pinEdit,g_savePin,g_addressLabel,g_copyAddress,g_showQr,g_noiseMode,g_noiseState}) showCtrl(h,open);','visibility')
old='''if(type==(uint8_t)pbr::Type::Pair){ bool ok=(extractPin(payload)==narrow(g_expectedPin)); g_paired=ok; postText(WM_PB_STATUS,ok?L"Paired: "+widen(device)+L" - camera and microphone ready":L"Pairing PIN rejected"); if(!ok) break;\n                setRemoteVideo(g_videoEnabled.load()); setRemoteAudio(g_audioEnabled.load()); applyStreamConfig();'''
new='''if(type==(uint8_t)pbr::Type::Pair){\n                bool pinOk=(extractPin(payload)==narrow(g_expectedPin));\n                bool qrOk=consumeQrToken(extractJsonString(payload,"token"));\n                bool ok=pinOk||qrOk; g_paired=ok;\n                postText(WM_PB_STATUS,ok?(qrOk?L"QR paired: "+widen(device)+L" - trusted connection saved":L"Paired: "+widen(device)+L" - camera and microphone ready"):L"Pairing PIN / QR token rejected");\n                if(!ok) break;\n                if(qrOk) sendControl(std::string("{\\\"cmd\\\":\\\"qrTrusted\\\",\\\"pin\\\":\\\"")+narrow(g_expectedPin)+"\\\"}");\n                setRemoteVideo(g_videoEnabled.load()); setRemoteAudio(g_audioEnabled.load()); applyStreamConfig();'''
rep(old,new,'pair auth')
old='''const int16_t* samples=(const int16_t*)payload.data(); uint32_t count=(uint32_t)(payload.size()/2); audio.writePcm16(samples,count,48000,1); audioPackets++;\n                if(g_vbCableEnabled.load()){\n                    std::wstring cableError;\n                    if(!vbCable.pushMonoPcm16(samples,count,&cableError)){'''
new='''const int16_t* samples=(const int16_t*)payload.data(); uint32_t count=(uint32_t)(payload.size()/2);\n                std::vector<int16_t> cleaned;\n                const int16_t* voiceSamples=samples;\n                if(g_noiseCleaner.mode()!=NoiseCleaner::Off){ g_noiseCleaner.process(samples,count,cleaned); voiceSamples=cleaned.data(); }\n                audio.writePcm16(voiceSamples,count,48000,1); audioPackets++;\n                static int lastNoiseState=-1; int ns=(int)g_noiseCleaner.activity();\n                if(ns!=lastNoiseState){ lastNoiseState=ns; if(g_hwnd) PostMessageW(g_hwnd,WM_PB_NOISE_STATE,(WPARAM)ns,0); }\n                if(g_vbCableEnabled.load()){\n                    std::wstring cableError;\n                    if(!vbCable.pushMonoPcm16(voiceSamples,count,&cableError)){'''
rep(old,new,'audio clean feed')
rep('int level=calculateLevel(samples,count); g_audioLevel=level;', 'int level=calculateLevel(voiceSamples,count); g_audioLevel=level;', 'level clean')
rep('if(g_recorder.active() && !g_recorder.writeAudio(samples,count)){', 'if(g_recorder.active() && !g_recorder.writeAudio(voiceSamples,count)){', 'record clean')
rep('MoveWindow(g_copyAddress,x,164,bw,28,TRUE);', 'MoveWindow(g_copyAddress,x,164,half,28,TRUE);\n        MoveWindow(g_showQr,x+half+gap,164,half,28,TRUE);', 'layout qr')
rep('MoveWindow(g_vbCable,x,716,bw,26,TRUE);\n        MoveWindow(g_audioDevices,x,746,half,28,TRUE);\n        MoveWindow(g_getVbCable,x+half+gap,746,half,28,TRUE);\n        MoveWindow(g_openCam,x,778,half,28,TRUE);\n        MoveWindow(g_openSound,x+half+gap,778,half,28,TRUE);\n        MoveWindow(g_testCamera,x,810,half,28,TRUE);\n        MoveWindow(g_repairCamera,x+half+gap,810,half,28,TRUE);\n        MoveWindow(g_audioLabel,x,844,bw,20,TRUE);\n        MoveWindow(g_audioBar,x,868,bw,20,TRUE);\n        MoveWindow(g_stats,x,892,bw,std::max(20,h-906),TRUE);', '''MoveWindow(g_vbCable,x,716,bw,26,TRUE);\n        MoveWindow(g_noiseMode,x,746,bw,120,TRUE);\n        MoveWindow(g_noiseState,x,778,bw,24,TRUE);\n        MoveWindow(g_audioDevices,x,806,half,28,TRUE);\n        MoveWindow(g_getVbCable,x+half+gap,806,half,28,TRUE);\n        MoveWindow(g_openCam,x,838,half,28,TRUE);\n        MoveWindow(g_openSound,x+half+gap,838,half,28,TRUE);\n        MoveWindow(g_testCamera,x,870,half,28,TRUE);\n        MoveWindow(g_repairCamera,x+half+gap,870,half,28,TRUE);\n        MoveWindow(g_audioLabel,x,904,bw,20,TRUE);\n        MoveWindow(g_audioBar,x,928,bw,20,TRUE);\n        MoveWindow(g_stats,x,952,bw,std::max(20,h-966),TRUE);''','layout noise')
rep('g_copyAddress=CreateWindowW(L"BUTTON",L"Copy PC address",WS_CHILD|WS_VISIBLE|BS_PUSHBUTTON,0,0,0,0,hwnd,(HMENU)IDC_COPY_ADDRESS,nullptr,nullptr);\n', '''g_copyAddress=CreateWindowW(L"BUTTON",L"Copy PC address",WS_CHILD|WS_VISIBLE|BS_PUSHBUTTON,0,0,0,0,hwnd,(HMENU)IDC_COPY_ADDRESS,nullptr,nullptr);\n        g_showQr=CreateWindowW(L"BUTTON",L"Show pairing QR",WS_CHILD|WS_VISIBLE|BS_PUSHBUTTON,0,0,0,0,hwnd,(HMENU)IDC_SHOW_QR,nullptr,nullptr);\n        g_noiseMode=CreateWindowW(WC_COMBOBOXW,L"",WS_CHILD|WS_VISIBLE|CBS_DROPDOWNLIST|WS_VSCROLL,0,0,0,0,hwnd,(HMENU)IDC_NOISE_MODE,nullptr,nullptr);\n        g_noiseState=CreateWindowW(L"STATIC",L"Noise Clean: OFF",WS_CHILD|WS_VISIBLE|SS_LEFT,0,0,0,0,hwnd,(HMENU)IDC_NOISE_STATE,nullptr,nullptr);\n''','create controls')
rep('for(HWND c:{g_status,g_share,g_camera,g_mic,g_switch,g_torch,g_streamLabel,g_applyCfg,g_snapshot,g_record,g_startup,g_openCam,g_openSound,g_vbCable,g_audioDevices,g_getVbCable,g_testCamera,g_repairCamera,g_audioLabel,g_stats,g_resolution,g_fps,g_settingsButton,g_rememberButtons,g_runWith,g_pinEdit,g_savePin,g_addressLabel,g_copyAddress}) SendMessageW(c,WM_SETFONT,(WPARAM)font,TRUE);', 'for(HWND c:{g_status,g_share,g_camera,g_mic,g_switch,g_torch,g_streamLabel,g_applyCfg,g_snapshot,g_record,g_startup,g_openCam,g_openSound,g_vbCable,g_audioDevices,g_getVbCable,g_testCamera,g_repairCamera,g_audioLabel,g_stats,g_resolution,g_fps,g_settingsButton,g_rememberButtons,g_runWith,g_pinEdit,g_savePin,g_addressLabel,g_copyAddress,g_showQr,g_noiseMode,g_noiseState}) SendMessageW(c,WM_SETFONT,(WPARAM)font,TRUE);','font list')
rep('ComboBox_SetCurSel(g_runWith,g_uiPrefs.runWith);\n', '''ComboBox_SetCurSel(g_runWith,g_uiPrefs.runWith);\n        ComboBox_AddString(g_noiseMode,L"Noise Clean: OFF (original audio)");\n        ComboBox_AddString(g_noiseMode,L"Noise Clean: Natural (recommended)");\n        ComboBox_AddString(g_noiseMode,L"Noise Clean: Strong");\n        ComboBox_SetCurSel(g_noiseMode,g_uiPrefs.noiseMode); g_noiseCleaner.setMode(g_uiPrefs.noiseMode);\n''','noise combo setup')
rep('case WM_PB_CABLE_STATE: Button_SetCheck(g_vbCable,wp?BST_CHECKED:BST_UNCHECKED); g_vbCableEnabled=(wp!=0); rememberCurrentButtons(); return 0;\n', '''case WM_PB_CABLE_STATE: Button_SetCheck(g_vbCable,wp?BST_CHECKED:BST_UNCHECKED); g_vbCableEnabled=(wp!=0); rememberCurrentButtons(); return 0;\n    case WM_PB_NOISE_STATE:{ std::wstring t=noiseActivityText(); if(g_noiseState) SetWindowTextW(g_noiseState,t.c_str()); if(g_audioLabel) SetWindowTextW(g_audioLabel,(L"Microphone level • "+t).c_str()); return 0; }\n''','noise message')
rep('if(id==IDC_RUN_WITH && code==CBN_SELCHANGE){ g_uiPrefs.runWith=std::max(0,(int)ComboBox_GetCurSel(g_runWith)); saveUiPrefs(); return 0; }\n', '''if(id==IDC_RUN_WITH && code==CBN_SELCHANGE){ g_uiPrefs.runWith=std::max(0,(int)ComboBox_GetCurSel(g_runWith)); saveUiPrefs(); return 0; }\n        if(id==IDC_NOISE_MODE && code==CBN_SELCHANGE){ g_uiPrefs.noiseMode=std::clamp((int)ComboBox_GetCurSel(g_noiseMode),0,2); saveUiPrefs(); g_noiseCleaner.setMode(g_uiPrefs.noiseMode); PostMessageW(hwnd,WM_PB_NOISE_STATE,(WPARAM)g_uiPrefs.noiseMode,0); postText(WM_PB_STATUS,g_uiPrefs.noiseMode==0?L"Noise Clean OFF • original PhoneBridge audio":(g_uiPrefs.noiseMode==1?L"Noise Clean Natural • stay quiet briefly so PhoneBridge can learn the background":L"Noise Clean Strong • stay quiet briefly so PhoneBridge can learn the background")); return 0; }\n''','noise command')
rep('if(id==IDC_COPY_ADDRESS){ std::wstring ip=localIps(); if(copyText(hwnd,ip)) postText(WM_PB_STATUS,L"PC address copied: "+ip); else postText(WM_PB_STATUS,L"Could not copy PC address"); return 0; }\n', '''if(id==IDC_COPY_ADDRESS){ std::wstring ip=localIps(); if(copyText(hwnd,ip)) postText(WM_PB_STATUS,L"PC address copied: "+ip); else postText(WM_PB_STATUS,L"Could not copy PC address"); return 0; }\n        if(id==IDC_SHOW_QR){ showPairingQr(hwnd); return 0; }\n''','qr command')
s=s.replace('PhoneBridge v1.8 • waiting for phone','PhoneBridge v1.9 • QR pairing + Noise Clean')
s=s.replace('PhoneBridge v1.8 starting','PhoneBridge v1.9 starting')
s=s.replace(r'L"Local\PhoneBridge-v1.8-SingleInstance"',r'L"Local\\PhoneBridge-v1.9-SingleInstance"')
s=s.replace('L"PhoneBridge v1.8 - Camera & Microphone"','L"PhoneBridge v1.9 - Camera & Microphone"')
s=s.replace('1240,940','1240,1000')

for marker in ['qrcodegen::QrCode::encodeText','consumeQrToken','NoiseCleaner g_noiseCleaner','Noise Clean: Natural','qrTrusted','writeAudio(voiceSamples,count)']:
    if marker not in s: raise SystemExit('missing v1.9 marker '+marker)
p.write_text(s,encoding='utf-8',newline='\n')
print('Applied PhoneBridge v1.9 Windows QR pairing + adaptive noise clean on v1.8 UI baseline')
